import os

def create_guest_list_file(guests):
    with open('guest_list.txt', 'w') as f:
        for guest in guests:
            f.write(guest + '\n')

def add_guest_to_list(guest):
    with open('guest_list.txt', 'a') as f:
        f.write(guest + '\n')

def read_guest_list():
    with open('guest_list.txt', 'r') as f:
        return f.readlines()

def main():
    guests = ['George Washington', 'Thomas Jefferson', 'Benjamin Franklin']
    create_guest_list_file(guests)

    add_guest_to_list('Alexander Hamilton')

    guest_list = read_guest_list()
    print(guest_list)

if __name__ == '__main__':
    main()

